import{_ as t,o as a,c as o,ae as s}from"./chunks/framework.DQC_QtFV.js";const m=JSON.parse('{"title":"How it works","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/how-it-works.md","filePath":"en/guide/how-it-works.md","lastUpdated":1793162416000}'),n={name:"en/guide/how-it-works.md"};function r(i,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h1><p>The assistant is one long-running agent with a single session per account, working one turn at a time. This page is the mechanism overview; the full detail is the repository&#39;s <a href="https://github.com/4fuu/personal-bot/blob/main/docs/how-it-works.md" target="_blank" rel="noreferrer">docs/how-it-works.md</a> and this page links to it rather than repeating it.</p><h2 id="what-starts-a-turn" tabindex="-1">What starts a turn <a class="header-anchor" href="#what-starts-a-turn" aria-label="Permalink to &quot;What starts a turn&quot;">​</a></h2><ul><li><strong>Messages.</strong> A private message, or a group message that @s the assistant, replies to it or names it, starts a turn according to that conversation&#39;s policy; other group messages may start one when it decides to join in.</li><li><strong>Wake words.</strong> When it ends a turn quietly, it can arm a few words; for six hours, any of them in that conversation starts a new turn.</li><li><strong><code>wait</code>.</strong> It can say &quot;look again in a while&quot;, from one minute to one day; when the time comes the conversation reopens with its newest messages.</li><li><strong>Scheduled tasks.</strong> Set in an admin&#39;s private chat, each opening a turn in a chosen conversation with the task&#39;s note as its input.</li><li><strong>Free turns.</strong> When a set number of minutes passes with no turn at all, it gets a turn of its own that belongs to no conversation. Off by default; the interval is set on <a href="./console/advanced.html">Advanced</a>.</li></ul><h2 id="one-batch-one-decision" tabindex="-1">One batch, one decision <a class="header-anchor" href="#one-batch-one-decision" aria-label="Permalink to &quot;One batch, one decision&quot;">​</a></h2><p>Messages are collected briefly first: longer while the same person keeps typing, shorter when someone else answers, at most a second when it is @&#39;d, never more than about eight seconds for a whole batch. In a group, Jev scores whether joining in is natural; the stack subtracts a small penalty when it has just been talking, a little less when the batch @s it. After a few batches in a row where it stayed out, the next check waits longer - messages are held, not dropped. When several conversations are waiting, the one that has waited too long goes first, and Jev may reorder the rest by urgency.</p><h2 id="one-session-rotating-windows" tabindex="-1">One session, rotating windows <a class="header-anchor" href="#one-session-rotating-windows" aria-label="Permalink to &quot;One session, rotating windows&quot;">​</a></h2><p>The working memory is not one transcript that grows forever. It is a sequence of context windows, each with a token budget, and a window is replaced when tokens - never a turn count - say so. While a window is open its beginning never changes, which keeps the model provider&#39;s prompt cache valid. As a window fills, the stack sends staged reminders that ask it to write notes and prepare a handoff; at the hard limit the stack rolls over by itself. A new window opens with a fixed opening note, the active notes, the handoff and the chat&#39;s recent messages; the previous window is not replayed, but its notes, its own history and the chat log all stay reachable.</p><h2 id="notes-the-only-long-term-memory" tabindex="-1">Notes: the only long-term memory <a class="header-anchor" href="#notes-the-only-long-term-memory" aria-label="Permalink to &quot;Notes: the only long-term memory&quot;">​</a></h2><p>Notes are written by the assistant itself; each carries a summary of at most 200 characters and a share of the token budget. Every new window keeps an active set</p><ul><li>the pinned notes, the notes written or edited in the closing window, then the rest by measured usage - and everything else stays archived and searchable. Notes are append-only and anchored to the messages and actions they came from, so a note keeps pointing at its sources after it is edited. Browse them on <a href="./console/memory.html">Memory</a>.</li></ul><h2 id="jev-yes-no-judgments" tabindex="-1">Jev: yes/no judgments <a class="header-anchor" href="#jev-yes-no-judgments" aria-label="Permalink to &quot;Jev: yes/no judgments&quot;">​</a></h2><p><a href="https://typesafe.ai/" target="_blank" rel="noreferrer">Jev</a> is TypeSafe AI&#39;s decision model.</p><p>Jev never writes replies; it answers short yes/no questions with a probability, and the stack compares that against a threshold. It is used for joining in, reply timing, quoting, queue order, the review of every outbound bubble, the network gate for a domain on neither list, and which notes stay active at rollover. Each decision has its own mode - off, shadow (asked and logged, the plain rule still acts) or on - and a new decision ships in shadow.</p><h2 id="compared-with-other-projects" tabindex="-1">Compared with other projects <a class="header-anchor" href="#compared-with-other-projects" aria-label="Permalink to &quot;Compared with other projects&quot;">​</a></h2><p>The side-by-side comparison of the context handling (AstrBot, MaiBot, DeepSeek Harness and pi) is the last part of <a href="https://github.com/4fuu/personal-bot/blob/main/docs/how-it-works.md" target="_blank" rel="noreferrer">docs/how-it-works.md</a>.</p>',16)])])}const p=t(n,[["render",r]]);export{m as __pageData,p as default};
